const items = $input.all();

return items.map(item => {
  const city = (item.json.city || "Unknown").trim();
  const baseDir = item.json.baseDir;

  const now = new Date();
  const timestamp = now.toISOString().replace(/[:.]/g, '-');

  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, '0');
  const day = String(now.getDate()).padStart(2, '0');

  const dirPath = `${baseDir}/${city}/${year}/${month}/${day}`;
  const fileName = `${city}_${timestamp}.json`;
  const fullPath = `${dirPath}/${fileName}`;

  return {
    json: {
      fullPath,
      city,
      raw_payload: item.json
    }
  };
});

const item = $input.item.json;
const raw = item.raw_payload || item;
const hourly = raw.hourly;
const city = (item.city || "Unknown").trim();
const cityClean = city.charAt(0).toUpperCase() + city.slice(1).toLowerCase();

const now = new Date();

const records = hourly.time.map((timestamp, i) => ({
  city: cityClean,
  timestamp: timestamp,
  pm10: hourly.pm10 ? hourly.pm10[i] : null,
  pm2_5: hourly.pm2_5 ? hourly.pm2_5[i] : null,
  co: hourly.carbon_monoxide ? hourly.carbon_monoxide[i] : null,
  no2: hourly.nitrogen_dioxide ? hourly.nitrogen_dioxide[i] : null,
  so2: hourly.sulphur_dioxide ? hourly.sulphur_dioxide[i] : null,
  ozone: hourly.ozone ? hourly.ozone[i] : null,
  european_aqi: hourly.european_aqi ? hourly.european_aqi[i] : null,
}));

const pastOnly = records.filter(r => new Date(r.timestamp) <= now);
const cleaned = pastOnly.filter(r => r.pm2_5 !== null && r.pm10 !== null);

const seen = new Set();
const deduped = cleaned.filter(r => {
  const key = `${r.city}_${r.timestamp}`;
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

return deduped.map(r => ({ json: r }));
